def crear_area_libre(apps, schema_editor):
    """Cada bodega existente recibe un "Área libre principal" con la capacidad que tenía,
    y todo su stock y sus herramientas pasan a ese espacio (no se pierde nada)."""
    Bodega = apps.get_model('bodegaApp', 'Bodega')
    Espacio = apps.get_model('bodegaApp', 'Espacio')
    Stock = apps.get_model('bodegaApp', 'Stock')
    Unidad = apps.get_model('bodegaApp', 'Unidad')
    Movimiento = apps.get_model('bodegaApp', 'MovimientoStock')
    for bodega in Bodega.objects.all():
        espacio = Espacio.objects.create(bodega=bodega, tipo='area', nombre='Área libre principal',
                                         capacidad=bodega.capacidad)
        Stock.objects.filter(bodega=bodega).update(espacio=espacio)
        Unidad.objects.filter(bodega=bodega).update(espacio=espacio)
        Movimiento.objects.filter(bodega=bodega).update(espacio=espacio)


